static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 输入形状：(batch, m, k) 和 (batch, k, n)
    const auto* A_shape = context->GetInputShape(0);
    const auto* B_shape = context->GetInputShape(1);
    if (A_shape == nullptr || B_shape == nullptr) {
        return ge::GRAPH_FAILED;
    }
    auto A_origin = A_shape->GetOriginShape();
    auto B_origin = B_shape->GetOriginShape();
    if (A_origin.GetDimNum() != 3 || B_origin.GetDimNum() != 3) {
        return ge::GRAPH_FAILED;
    }

    uint32_t batch = static_cast<uint32_t>(A_origin.GetDim(0));
    uint32_t m = static_cast<uint32_t>(A_origin.GetDim(1));
    uint32_t k = static_cast<uint32_t>(A_origin.GetDim(2));
    uint32_t n = static_cast<uint32_t>(B_origin.GetDim(2));

    // 设置Block数量（简化为单核，确保正确性；可按需调优）
    context->SetBlockDim(1);

    BatchedMatrixMultiplicationCustomTilingData tiling;
    tiling.set_m(m);
    tiling.set_n(n);
    tiling.set_k(k);
    tiling.set_batch(batch);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t* workspace = context->GetWorkspaceSizes(1);
    workspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {

static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* A_shape = context->GetInputShape(0);
    const gert::Shape* B_shape = context->GetInputShape(1);
    if (A_shape == nullptr || B_shape == nullptr) {
        return GRAPH_FAILED;
    }
    // 输出形状：(batch, m, n)
    gert::Shape* C_shape = context->GetOutputShape(0);
    gert::Shape out_shape;
    out_shape.SetDimNum(3);
    out_shape.SetDim(0, A_shape->GetDim(0));
    out_shape.SetDim(1, A_shape->GetDim(1));
    out_shape.SetDim(2, B_shape->GetDim(2));
    *C_shape = out_shape;
    return GRAPH_SUCCESS;
}

